export enum Partner_Order_Item_State_Enum {
  /** when item accepted by franchise */
  Accepted = 'ACCEPTED',
  /** APPROVAL */
  Approval = 'APPROVAL',
  /** when task assigned to the driver vehicle */
  Assigned = 'ASSIGNED',
  /** when item is cancelled */
  Cancelled = 'CANCELLED',
  /** when order mark paid, order item status is confirmed */
  Confirmed = 'CONFIRMED',
  /** when item is delivered */
  Delivered = 'DELIVERED',
  /** IN_PROGRESS */
  InProgress = 'IN_PROGRESS',
  /** when vehicle  is moving */
  InTransit = 'IN_TRANSIT',
  /** NO_SHOW */
  NoShow = 'NO_SHOW',
  /** when order create, order item status is pending */
  Pending = 'PENDING',
  /** when item is pickup */
  Pickup = 'PICKUP'
}

