export enum Task_State_Enum {
  /** when task is accepted by driver vehicle */
  Accepted = 'ACCEPTED',
  /** when driver vehicle reached to location */
  Arrived = 'ARRIVED',
  /** when task is assigned to driver vehicle */
  Assigned = 'ASSIGNED',
  /** when driver vehicle ask to cancel trip */
  CancellationRequested = 'CANCELLATION_REQUESTED',
  /** when task is cancelled */
  Cancelled = 'CANCELLED',
  /** when driver vehicle delivered  fuel or consumable items */
  Delivered = 'DELIVERED',
  /** when driver vehicle start to dispense fuel or consumable items */
  Dispensing = 'DISPENSING',
  /** when driver vehicle travel to location */
  InTransit = 'IN_TRANSIT',
  /** when task is not assigned to driver vehicle */
  Open = 'OPEN',
  /** when driver vehicle reject task */
  Rejected = 'REJECTED',
  /** when task is rescheduled */
  Rescheduled = 'RESCHEDULED',
  /** when driver vehicle schedule trip */
  Schedule = 'SCHEDULE',
  /** when driver vehicle start trip */
  Started = 'STARTED'
}

